-- 0066: 网关内申请数据查询权限(#173)。与 migrations/0066_query_grant_request.sql 同一份结构,说明见那边。
CREATE TABLE IF NOT EXISTS "tbl_query_grant_request" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NOT NULL,
  "connection_id" bigint NOT NULL,
  "db_name" citext NOT NULL CHECK (char_length("db_name") <= 128),
  "days" integer NOT NULL,
  "allow_export" boolean NOT NULL DEFAULT false,
  "reason" citext NOT NULL DEFAULT '' CHECK (char_length("reason") <= 512),
  "approval_id" bigint NOT NULL DEFAULT 0,
  "grant_id" bigint NOT NULL DEFAULT 0,
  "error" citext NOT NULL DEFAULT '' CHECK (char_length("error") <= 512),
  "created_at" timestamptz(3),
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "tbl_query_grant_request__idx_qgr_user" ON "tbl_query_grant_request" ("user_id");
CREATE INDEX IF NOT EXISTS "tbl_query_grant_request__idx_qgr_approval" ON "tbl_query_grant_request" ("approval_id");

ALTER TABLE "tbl_approval"
  ADD COLUMN IF NOT EXISTS "query_grant_req_id" bigint NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS "tbl_approval__idx_approval_qgr" ON "tbl_approval" ("query_grant_req_id");
